    node=next(n for n in ast.walk(ast.parse(source)) if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='hyperparameter_defaults' for t in n.targets));return {k.arg:ast.literal_eval(k.value) for k in node.value.keywords}
